    import time

    LANGUAGE_WRAPPER = "A factory produces widgets using a robot arm. On each step, the robot can either perform a 'weld' operation or a 'cool' operation. Due to a design flaw, if the robot performs {k} or more 'weld' operations consecutively, it overheats and shuts down. For any given step, the robot supervisor programs it to 'weld' with probability {a}/{b} and to 'cool' with probability 1 - {a}/{b}, independent of previous steps. For a process that requires {n} steps, what is the probability that the robot completes it without overheating? If this probability is i/j in lowest terms, find i+j."

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
k = rng.choice([3, 4])
b = rng.choice([3, 4, 5])
a = rng.randint(1, b - 1)
n = rng.randint(k + 3, k + 8)

# Ensure the problem is not the fair coin seed problem case
# This is also checked by the verifier, but good practice to avoid it here.
if k == 2 and a * 2 == b:
    a = (a + 1) % b
    if a == 0: a = b-1

return {
    'n': n,
    'k': k,
    'a': a,
    'b': b,
}

