if not (n >= k):
    return False, None  # n must be at least k for the question to be non-trivial

# Difficulty constraints
if n < k + 2:
    return False, None  # Recurrence must be used at least once
if k == 2 and a * 2 == b:
    return False, None  # Avoid the structure of the seed problem (k=2, p=1/2)

def gcd(x, y):
    while y:
        x, y = y, x % y
    return abs(x)

try:
    # Let A_m be the probability of a valid sequence of length m.
    # The recurrence is A_m = A_{m-1} - (1-p)*p^k * A_{m-k-1} for m >= k+1.
    # To avoid fractions, we use an integer recurrence for D_m = b^m * A_m.
    # D_m = b * D_{m-1} - a^k * (b-a) * D_{m-k-1}

    # Base cases for D_m
    D = {}
    for i in range(k):
        D[i] = b**i
    D[k] = b**k - a**k

    if n <= k:
        num = D[n]
        den = b**n
    else:
        # Fill DP table up to n using the recurrence
        for m in range(k + 1, n + 1):
            term1 = b * D[m - 1]
            term2 = (a**k) * (b - a) * D[m - (k + 1)]
            D[m] = term1 - term2
        num = D[n]
        den = b**n

    common_divisor = gcd(num, den)
    i = num // common_divisor
    j = den // common_divisor

    return True, i + j

except (KeyError, OverflowError, ValueError):
    # Catch potential errors during calculation
